    store.write("Mode", "fast")
    assert store.delete("Mode") is True
    assert store.delete("Mode") is False


def test_unknown_view_rejected():
    with pytest.raises(ValueError):
        ConfigStore(winreg.HKEY_LOCAL_MACHINE, BASE, view="128")

