    """某个注册表路径下的配置节。

    ``view`` 取 ``"default"`` / ``"64"`` / ``"32"``，决定访问哪一个注册表视图。

    本节的所有操作（存在性判定、读、写、删值、删节）都在同一个视图内进行，
    因此 32 位程序写下的配置只会出现在 ``view="32"`` 的 ``ConfigStore`` 里。
    """

    def __init__(self, hive, path, view="default"):
        if view not in VIEWS:
            raise ValueError("unknown view: %r" % (view,))
        self.hive = hive
        self.path = path
        self.view = view

    # -- 内部 ---------------------------------------------------------------

    @property
    def flags(self):
        """本视图对应的 WOW64 标志，附加在每一次注册表访问上。"""
        return view_flags(self.view)

    def _open(self, access):
        return winreg.OpenKey(self.hive, self.path, 0, access | self.flags)

    def _create(self, access):
        return winreg.CreateKeyEx(self.hive, self.path, 0, access | self.flags)

    def child(self, name):
        """返回本节的子节。"""
        return ConfigStore(self.hive, "%s\\%s" % (self.path, name), self.view)

    # -- 查询 ---------------------------------------------------------------

    def exists(self):
        """配置节当前是否存在（在所选视图内）。"""
        try:
            with self._open(winreg.KEY_READ):
                return True
        except FileNotFoundError:
            return False

    def names(self):
        """返回本节下的值名列表。"""
        try:
            with self._open(winreg.KEY_READ) as key:
                count = winreg.QueryInfoKey(key)[1]
                return [winreg.EnumValue(key, i)[0] for i in range(count)]
        except FileNotFoundError:
            return []

    def read(self, name, default=_MISSING):
        """读取一个值；缺失时返回 ``default`` 或抛 :class:`ConfigError`。

        与 :meth:`exists` 一样，读取也在所选视图内进行：只有当前视图里确实
        存在该值时才返回它，否则按缺失处理。
        """
        try:
            with self._open(winreg.KEY_READ) as key:
                value, _kind = winreg.QueryValueEx(key, name)
                return value
        except FileNotFoundError:
            if default is _MISSING:
                raise ConfigError("missing value %r in %s" % (name, self.path))
            return default

    # -- 修改 ---------------------------------------------------------------

    def write(self, name, value):
        """写入一个字符串值。"""
        with self._create(winreg.KEY_WRITE) as key:
            winreg.SetValueEx(key, name, 0, winreg.REG_SZ, str(value))

    def delete(self, name):
        """删除一个值；值不存在时返回 ``False``。"""
        try:
            with self._open(winreg.KEY_WRITE) as key:
                winreg.DeleteValue(key, name)
                return True
        except FileNotFoundError:
            return False

    def delete_tree(self):
        """删除整个配置节，连同它下面的所有子键。

        删除在所选视图内进行，所以卸载时另一个视图里的残留配置也能被清掉。

        返回该配置节此前是否存在：存在并已删除返回 ``True``，
        本来就不存在返回 ``False``。
        """
        try:
            with self._open(winreg.KEY_READ | _DELETE_ACCESS) as key:
                self._delete_children(key)
        except FileNotFoundError:
            return False
        try:
            winreg.DeleteKeyEx(self.hive, self.path, self.flags, 0)
        except FileNotFoundError:
            return False
        return True

    def _delete_children(self, key):
        """递归删除已打开的 ``key`` 下面的全部子键。

        ``winreg.DeleteKey`` / ``DeleteKeyEx`` 都不接受带子键的键（Windows 会
        返回 ``ERROR_ACCESS_DENIED``），因此必须先自底向上把子键删干净。
        子键始终相对父句柄打开，并附加本视图的 WOW64 标志，保证不会跨视图误删。
        """
        while True:
            try:
                name = winreg.EnumKey(key, 0)
            except OSError:
                # ERROR_NO_MORE_ITEMS：子键已经删完。
                return
            with winreg.OpenKey(
                key, name, 0, winreg.KEY_READ | _DELETE_ACCESS | self.flags
            ) as child:
                self._delete_children(child)
            winreg.DeleteKeyEx(key, name, self.flags, 0)

